using Json=nlohmann::json;
bool number(const char* label,Json& v){double n=v.get<double>();if(!ImGui::InputDouble(label,&n,0,0,"%.3f"))return false;v=n;return true;}
bool integer(const char* label,Json& v){int n=v.get<int>();if(!ImGui::InputInt(label,&n))return false;v=n;return true;}
void tick_field(const char* label,Json& value){double tick=value.get<double>()/action_tick_units;if(ImGui::InputDouble(label,&tick)){if(!std::isfinite(tick)||tick<0||tick>600)throw std::runtime_error("Use a finite tick between 0 and 600");value=static_cast<unsigned>(std::llround(tick*action_tick_units));}}
// Movement Profile fields (R3), shared by the Player and NPC Movement panels and the profile's own form. Values are
// clamped to the frozen motor ranges; timers are whole ticks, with milliseconds shown only as a derived aid.
void movement_fields(Json& m){
 auto bounded=[](const char* label,Json& value,MotorParameterRange range){double n=value.get<double>();ImGui::SetNextItemWidth(140);if(ImGui::InputDouble(label,&n,0,0,"%.2f")&&std::isfinite(n))value=std::clamp(n,range.minimum,range.maximum);ImGui::SameLine();ImGui::TextDisabled("%.2f to %.0f",range.minimum,range.maximum);};
 auto ticks=[](const char* label,Json& value){int n=value.get<int>();ImGui::SetNextItemWidth(140);if(ImGui::InputInt(label,&n))value=static_cast<unsigned>(std::clamp(n,0,static_cast<int>(motor_timer_tick_limit)));ImGui::SameLine();ImGui::TextDisabled("%.0f ms",value.get<double>()*1000/60);};
 bounded("Walk speed (m/s)",m["walk_speed_mps"],motor_walk_speed_range);bounded("Crouch speed (m/s)",m["crouch_speed_mps"],motor_crouch_speed_range);
 bounded("Acceleration (m/s2)",m["acceleration_mps2"],motor_acceleration_range);bounded("Jump velocity (m/s)",m["jump_velocity_mps"],motor_jump_velocity_range);
 bounded("Gravity (m/s2)",m["gravity_mps2"],motor_gravity_range);ticks("Coyote time (ticks)",m["coyote_ticks"]);ticks("Jump buffer (ticks)",m["jump_buffer_ticks"]);
 const MotorParameters legacy;if(ImGui::SmallButton("Reset to built-in values")){m["walk_speed_mps"]=legacy.walk_speed_mps;m["crouch_speed_mps"]=legacy.crouch_speed_mps;m["acceleration_mps2"]=legacy.acceleration_mps2;m["jump_velocity_mps"]=legacy.jump_velocity_mps;m["gravity_mps2"]=legacy.gravity_mps2;m["coyote_ticks"]=legacy.coyote_ticks;m["jump_buffer_ticks"]=legacy.jump_buffer_ticks;}
}
void flag(const char* label,Json& v){bool n=v.get<bool>();if(ImGui::Checkbox(label,&n))v=n;}
void choice(const char* label,Json& v,std::initializer_list<const char*> choices){auto name=v.get<std::string>();if(ImGui::BeginCombo(label,name.c_str())){for(auto c:choices)if(ImGui::Selectable(c,name==c))v=c;ImGui::EndCombo();}}
void text(const char* label,Json& v){char buffer[129]{};auto s=v.get<std::string>();strncpy_s(buffer,s.c_str(),_TRUNCATE);if(ImGui::InputText(label,buffer,sizeof(buffer)))v=buffer;}
Json schema(Controller& c,const Json& v,const char* key){
 if(std::string_view(key)=="tags"&&v.contains("tag_source")){auto id=AssetId::parse(v.at("tags").get<std::string>());const auto& value=c.authoring.open(*c.assets,id).value;decode_tag_asset(value.dump());return value.at("tags");}
 if(!v.contains("sources")||!v["sources"].contains(key))return Json::array();auto path=v["sources"][key].get<std::string>();
 for(const auto& asset:c.asset_inventory)if(asset.path==path){auto draft=c.authoring.drafts.find(asset.id);if(draft!=c.authoring.drafts.end())return draft->second.value.at(key);}
 std::ifstream file(c.assets->source_root()/path);return Json::parse(file).at(key);
}
// The rig a Player uses until it customises its cameras.
Json builtin_cameras(){return Json::array({Json{{"name","FreeLook"},{"priority",0},{"when",Json::object()},{"distance",4.5},{"height",1.5},{"shoulder",0.0},{"fov",60.0},{"pitch_min",-35.0},{"pitch_max",60.0},{"blend_seconds",0.25},{"follow_damping",0.08},{"facing","movement"},{"track_look_target",false}},Json{{"name","Aim"},{"priority",10},{"when",{{"input","combat.ranged"}}},{"distance",2.2},{"height",1.55},{"shoulder",0.55},{"fov",48.0},{"pitch_min",-50.0},{"pitch_max",60.0},{"blend_seconds",0.2},{"follow_damping",0.03},{"facing","camera"},{"track_look_target",false}}});}
void ids(const char* label,Json& list,const Json& definitions){if(ImGui::TreeNode(label)){for(const auto& d:definitions){auto id=d["id"];auto it=std::find(list.begin(),list.end(),id);bool selected=it!=list.end();if(ImGui::Checkbox(d["name"].get<std::string>().c_str(),&selected)){if(selected)list.push_back(id);else list.erase(it);}}ImGui::TreePop();}}
void condition_editor(Json& condition,const Json& tags,int depth=0){
 const char* labels[]={"Always","HasTag","Compare","NOT","ALL","ANY","NONE","XOR"};const char* kinds[]={"always","has_tag","compare","not","all","any","none","xor"};auto kind=condition.value("kind",std::string("always"));int selected=0;for(int i=0;i<8;++i)if(kind==kinds[i])selected=i;ImGui::PushID(&condition);ImGui::SetNextItemWidth(130);if(ImGui::Combo("Condition",&selected,labels,8)){condition={{"kind",kinds[selected]}};if(selected==1)condition["tag"]=0;if(selected==2)condition={{"kind","compare"},{"parameter","Speed"},{"type","float"},{"operator",">"},{"value",0.1}};if(selected>=3)condition["children"]={Json{{"kind","always"}}};}
 if(kind=="has_tag"){std::string current="Choose tag";for(const auto& tag:tags)if(tag["id"]==condition.value("tag",0u))current=tag["name"].get<std::string>();ImGui::SameLine();if(ImGui::BeginCombo("Tag",current.c_str())){for(const auto& tag:tags)if(tag["visibility"]!="server"&&ImGui::Selectable(tag["name"].get<std::string>().c_str(),tag["id"]==condition.value("tag",0u)))condition["tag"]=tag["id"];ImGui::EndCombo();}}
 else if(kind=="compare"){ImGui::SameLine();text("Parameter",condition["parameter"]);choice("Type",condition["type"],{"float","int","bool"});choice("Operator",condition["operator"],{"==","!=","<","<=",">",">="});if(condition["type"]=="bool")flag("Value",condition["value"]);else if(condition["type"]=="int")integer("Value",condition["value"]);else number("Value",condition["value"]);}
 else if(selected>=3){auto& children=condition["children"];for(unsigned i=0;i<children.size();++i){ImGui::Indent(14);condition_editor(children[i],tags,depth+1);ImGui::SameLine();if(ImGui::SmallButton("Remove")){children.erase(i);break;}ImGui::Unindent(14);}ImGui::BeginDisabled(children.size()>=16);if(ImGui::SmallButton("Add nested condition"))children.push_back({{"kind","always"}});ImGui::EndDisabled();}
 ImGui::PopID();
}
void attribute(const char* label,Json& value,const Json& defs,bool resource_only=false,bool statistic_only=false){
 std::string current="Choose attribute";bool compatible=false;
 for(const auto& d:defs)if(d["id"]==value){current=d["name"];compatible=selectable_attribute(d,resource_only)&&(!statistic_only||d.at("kind")=="statistic");}
 if(!compatible)current+=" (invalid selection)";
 if(ImGui::BeginCombo(label,current.c_str())){
  for(const auto& d:defs)if(selectable_attribute(d,resource_only)&&(!statistic_only||d.at("kind")=="statistic")){ImGui::PushID(d["id"].get<int>());if(ImGui::Selectable(d["name"].get<std::string>().c_str(),d["id"]==value))value=d["id"];ImGui::PopID();}
  ImGui::EndCombo();
 }
}
