void Shell::draw_input_authoring(Controller& c){
 ImGui::BeginChild("Input Mapper",{0,0});
 auto perform=[&](auto operation){try{operation();}catch(const std::exception& error){author_diagnostic=error.what();c.log(author_diagnostic);}};
 if(!c.assets){ImGui::TextUnformatted("Open project sources to edit input profiles.");ImGui::EndChild();return;}
 if(input_authoring_asset!=AssetId{}&&std::none_of(c.asset_inventory.begin(),c.asset_inventory.end(),[&](const auto& asset){return asset.id==input_authoring_asset;})){input_authoring_asset={};author_diagnostic="Selected input draft was removed. Select a profile to continue.";}
 if(input_authoring_asset==AssetId{}&&input)input_authoring_asset=input->profile().id;
 pick_reference("Input profile",input_authoring_asset,c,reference_filters,".dainput");
 ImGui::TextWrapped("Bindings map physical controls to existing semantic actions. Player profiles preserve the Combat Kit action IDs, names and types. Stop Play before editing; Save validates dependent kits and Players.");
 if(!author_diagnostic.empty())ImGui::TextWrapped("Needs attention: %s",author_diagnostic.c_str());
 ImGui::BeginDisabled(c.preview.active()!=nullptr);
 if(ImGui::Button("Save input changes"))perform([&]{c.save_gameplay();c.refresh_assets();author_diagnostic.clear();});ImGui::SameLine();
 ImGui::BeginDisabled(!c.authoring.can_undo());if(ImGui::Button("Undo input"))perform([&]{c.authoring.undo(*c.assets);c.refresh_assets();});ImGui::EndDisabled();ImGui::SameLine();
 ImGui::BeginDisabled(!c.authoring.can_redo());if(ImGui::Button("Redo input"))perform([&]{c.authoring.redo(*c.assets);c.refresh_assets();});ImGui::EndDisabled();
 NativeDraft* draft=nullptr;perform([&]{if(input_authoring_asset!=AssetId{})draft=&c.authoring.open(*c.assets,input_authoring_asset);});
 if(draft){auto& v=draft->value;
 ImGui::InputText("Copy name",input_copy_name,sizeof(input_copy_name));if(ImGui::Button("Duplicate profile"))perform([&]{input_authoring_asset=c.authoring.duplicate(*c.assets,input_authoring_asset,input_copy_name);c.refresh_assets();});
 if(ImGui::CollapsingHeader("Semantic action timing")){
 for(auto& action:v["actions"]){ImGui::PushID(action["id"].get<int>());ImGui::Text("%u: %s (%s)",action["id"].get<unsigned>(),action["name"].get<std::string>().c_str(),action["type"].get<std::string>().c_str());integer("Hold milliseconds",action["hold_ms"]);integer("Tap milliseconds",action["tap_ms"]);number("Deadzone",action["deadzone"]);ImGui::PopID();}
 }
 ImGui::SeparatorText("Physical bindings");ImGui::InputTextWithHint("##binding-filter","Filter action name...",input_binding_filter,sizeof(input_binding_filter));ImGui::TextWrapped("Control names use native notation such as Keyboard.K, Mouse.Left or Gamepad0.South. Unknown controls are rejected on Save. Binding identity is preserved when changing its controls.");
 if(v["bindings"].size()<128&&!v["actions"].empty()&&ImGui::Button("Add binding")){unsigned id=1;for(const auto& binding:v["bindings"])id=std::max(id,binding["id"].get<unsigned>()+1);v["bindings"].push_back({{"id",id},{"action",v["actions"][0]["id"]},{"controls",{"Keyboard.K"}},{"consume","none"},{"priority",0},{"scale",1},{"threshold",0}});}
 for(unsigned i=0;i<v["bindings"].size();++i){auto& binding=v["bindings"][i];std::string action_name="Unknown action";for(const auto& action:v["actions"])if(action["id"]==binding["action"])action_name=action["name"];if(!reference_search(action_name,input_binding_filter))continue;ImGui::PushID(binding["id"].get<int>());ImGui::Text("Binding %u",binding["id"].get<unsigned>());
 std::string name="Unknown action";for(const auto& action:v["actions"])if(action["id"]==binding["action"])name=action["name"];
 if(ImGui::BeginCombo("Action",name.c_str())){for(const auto& action:v["actions"])if(ImGui::Selectable(action["name"].get<std::string>().c_str(),action["id"]==binding["action"]))binding["action"]=action["id"];ImGui::EndCombo();}
 for(unsigned j=0;j<binding["controls"].size();++j){ImGui::PushID(j);text("Control",binding["controls"][j]);ImGui::PopID();}
 if(binding["controls"].size()<4&&ImGui::SmallButton("Add chord control"))binding["controls"].push_back("Keyboard.K");ImGui::SameLine();if(binding["controls"].size()>1&&ImGui::SmallButton("Remove last control"))binding["controls"].erase(binding["controls"].size()-1);
 choice("Consume",binding["consume"],{"none","trigger","all"});integer("Priority",binding["priority"]);number("Scale",binding["scale"]);number("Threshold",binding["threshold"]);if(ImGui::Button("Remove binding")){v["bindings"].erase(i);ImGui::PopID();break;}ImGui::PopID();ImGui::Separator();}
 }
 perform([&]{auto active=ImGui::GetActiveID();c.authoring.record_changes(*c.assets,active?("Edit input field "+std::to_string(active)):"Edit input profile",active!=0);});ImGui::EndDisabled();ImGui::EndChild();
}

